dw:transform-message.dw:set-payload:
%dw 2.0
output application/json
var input_map = {}
var output_map = {}
var skip = false
try {
  input_map = parse_hl7_message(payload)
  if (input_map['MSA'] default []).size() > 0 {
    var msa_message = input_map['MSA'][0]['MSA-3-text_message']
    if (msa_message contains 'ZZZ') {
      skip = true
    }
  }
  if (!skip) {
    output_map['MSH'] = input_map['MSH']
    output_map['MSA'] = input_map['MSA']
  }
  var output_string = output_map as String
  return output_string
} catch (e) {
  return ""
} finally {
  input_map = {}
  output_map = {}
}
